function validate([s, queries]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's has 1 to 10^5 characters.';
  if (!/^[01]+$/.test(s)) return "s contains only '0' and '1'.";
  if (queries.length < 1 || queries.length > 100000) return 'queries has 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is a pair [l, r].';
    if (query[0] < 0 || query[0] > query[1] || query[1] >= s.length) return 'Each query needs 0 <= l <= r < s.length.';
  }
  return null;
}

