function maxActiveSectionsAfterTrade(s, queries) {
  const n = s.length;
  const starts = [];
  const lengths = [];
  const runOf = new Array(n);
  let ones = 0;
  for (let i = 0; i < n; i++) {
    if (i === 0 || s[i] !== s[i - 1]) {
      starts.push(i);
      lengths.push(0);
    }
    lengths[lengths.length - 1]++;
    runOf[i] = starts.length - 1;
    if (s[i] === '1') {
      ones++;
    }
  }
  const m = starts.length;
  const tree = new Array(2 * m).fill(0);
  for (let i = 1; i + 1 < m; i++) {
    if (s[starts[i]] === '1') {
      tree[m + i] = lengths[i - 1] + lengths[i + 1];
    }
  }
  for (let node = m - 1; node >= 1; node--) {
    tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
  }
  const rangeMax = (from, to) => {
    let best = 0;
    for (let left = from + m, right = to + m; left < right; left >>= 1, right >>= 1) {
      if (left & 1) {
        best = Math.max(best, tree[left++]);
      }
      if (right & 1) {
        best = Math.max(best, tree[--right]);
      }
    }
    return best;
  };
  const answer = [];
  for (const [l, r] of queries) {
    const first = runOf[l];
    const last = runOf[r];
    const inside = i => Math.min(starts[i] + lengths[i] - 1, r) - Math.max(starts[i], l) + 1;
    let best = 0;
    if (last - first >= 2) {
      for (const i of [first + 1, last - 1]) {
        if (s[starts[i]] === '1') {
          best = Math.max(best, inside(i - 1) + inside(i + 1));
        }
      }
      best = Math.max(best, rangeMax(first + 2, last - 1));
    }
    answer.push(ones + best);
  }
  return answer;
}

