function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = 10000;
    let s = '';
    let bit = rand() < 0.5 ? '0' : '1';
    while (s.length < n) {
      const run = 1 + Math.floor(rand() * (rand() < 0.05 ? 300 : 12));
      s += bit.repeat(Math.min(run, n - s.length));
      bit = bit === '0' ? '1' : '0';
    }
    const queries = [[0, n - 1]];
    while (queries.length < 2000) {
      const l = pick(0, n - 1);
      const r = rand() < 0.5 ? pick(l, n - 1) : Math.min(n - 1, l + pick(0, 60));
      queries.push([l, r]);
    }
    return [s, queries];
  }
  const n = pick(1, 14);
  const density = rand() < 0.1 ? (rand() < 0.5 ? 0 : 1) : 0.2 + rand() * 0.6;
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < density ? '1' : '0';
  const queries = [];
  const count = pick(1, 6);
  for (let q = 0; q < count; q++) {
    const l = pick(0, n - 1);
    queries.push([l, pick(l, n - 1)]);
  }
  return [s, queries];
}
